Q: What&#39;s the simplest way to reverse the order of bits in a byte in C/C++? A: <p>I'll chip in my solution, since I can't find anything like this in the answers so far. It is a bit overengineered maybe, but it generates the lookup table using <a href="https://en.wikipedia.org/wiki/C%2B%2B14" rel="nofollow noreferrer">C++14</a> <code>std::index_sequence</code> in compile time.</p>
<pre><code>#include &lt;array&gt;
#include &lt;utility&gt;

constexpr unsigned long reverse(uint8_t value) {
    uint8_t result = 0;
    for (std::size_t i = 0, j = 7; i &lt; 8; ++i, --j) {
        result |= ((value &amp; (1 &lt;&lt; j)) &gt;&gt; j) &lt;&lt; i;
    }
    return result;
}

template&lt;size_t... I&gt;
constexpr auto make_lookup_table(std::index_sequence&lt;I...&gt;)
{
    return std::array&lt;uint8_t, sizeof...(I)&gt;{reverse(I)...};
}

template&lt;typename Indices = std::make_index_sequence&lt;256&gt;&gt;
constexpr auto bit_reverse_lookup_table()
{
    return make_lookup_table(Indices{});
}

constexpr auto lookup = bit_reverse_lookup_table();

int main(int argc)
{
    return lookup[argc];
}
</code></pre>
